// Consolida las 3 tasas de Bolivia: oficial (fija), VRD (BCB diario) y
// paralelo (mediana Binance P2P). Ver onia-core/ONIA_EXCHANGE_RATE_AUTOPRICING_2026.md
const OFICIAL_COMPRA = 6.86;
const OFICIAL_VENTA = 6.96;

let paralelo = null;
try {
  const data = $('Binance P2P USDT/BOB').first().json;
  const prices = (data.data || [])
    .map((row) => Number(row?.adv?.price))
    .filter((price) => Number.isFinite(price) && price > 0)
    .sort((a, b) => a - b);
  if (prices.length) {
    paralelo = prices[Math.floor(prices.length / 2)];
  }
} catch (error) { /* sin datos binance */ }

let vrd = null;
try {
  const html = String($('BCB home (VRD)').first().json.data ?? $('BCB home (VRD)').first().json ?? '');
  const match = html.match(/VRD[^0-9]{0,80}([0-9]{1,2}[.,][0-9]{2})/i) || html.match(/[Rr]eferencial[^0-9]{0,80}([0-9]{1,2}[.,][0-9]{2})/);
  if (match) vrd = Number(match[1].replace(',', '.'));
} catch (error) { /* BCB no disponible */ }

const brechaPct = paralelo ? (((paralelo - OFICIAL_VENTA) / OFICIAL_VENTA) * 100).toFixed(1) : null;
const fecha = new Date().toLocaleDateString('es-BO', { timeZone: 'America/La_Paz', day: '2-digit', month: '2-digit', year: 'numeric' });

const lineas = [
  `Tipo de cambio Bolivia — ${fecha}`,
  ``,
  `Oficial BCB: ${OFICIAL_COMPRA} compra / ${OFICIAL_VENTA} venta (fijo)`,
  vrd ? `VRD (BCB, mercado bancario): ${vrd.toFixed(2)} Bs` : `VRD: no disponible hoy`,
  paralelo ? `Paralelo (Binance P2P mediana): ${paralelo.toFixed(2)} Bs` : `Paralelo: no disponible`,
  brechaPct ? `Brecha vs oficial: ${brechaPct}%` : null,
  ``,
  `Costo de reposicion de importadores sigue al paralelo/VRD.`,
].filter((line) => line !== null);

return [{ json: { text: lineas.join('\n'), oficialVenta: OFICIAL_VENTA, vrd, paralelo, brechaPct } }];
